#!/usr/bin/env python3
"""Generate C validation metadata, JSON Schema/OpenAPI and MCP tools from one catalog."""
from pathlib import Path
import argparse
import json
import re
import hashlib

ROOT=Path(__file__).resolve().parents[1]
CATALOG=ROOT/'api/control-v1.json'


def O(properties, required=()):
    return {'type':'object','properties':properties,'required':list(required),'additionalProperties':False}


def generate():
    data=json.loads(CATALOG.read_text())
    scopes=data['scopes']
    header=['// Generated by tools/generate_control_api.py; do not edit.','// SPDX-License-Identifier: Apache-2.0','#pragma once','#include "control_protocol.h"']
    for index,name in enumerate(scopes):
        header.append(f'#define CP_SCOPE_{name.upper().replace(".","_")} (UINT64_C(1) << {index})')
    header.append('#define CP_SCOPE_ALL ((UINT64_C(1) << '+str(len(scopes))+') - 1U)')
    for op in data['operations']:
        ident=op['name'].upper().replace('.','_')
        header.append(f'#define CP_OP_{ident} {op["id"]}U')
    header += ['cp_scope_mask_t cp_scope_from_name(const char *);','const char *cp_scope_name(size_t);','bool cp_operation_flag(cp_operation_id_t, const char *);','const char *cp_catalog_sha256(void);']
    private=['// Generated by tools/generate_control_api.py; do not edit.','// SPDX-License-Identifier: Apache-2.0','#include <float.h>','#include <string.h>','#include "control_registry.h"','#include "control_registry_internal.h"']
    counter=0
    def literal(value):return json.dumps(value,ensure_ascii=True)
    def schema(s):
        nonlocal counter
        name=f'schema_{counter}';counter+=1
        typ=s['type'];fields=[f'.type = CJ_{"BOOL" if typ == "boolean" else typ.upper()}']
        if typ=='object':
            props=[]
            for key,child in s.get('properties',{}).items():props.append((key,schema(child),key in s.get('required',[])))
            if props:
                private.append(f'static const cs_property_t {name}_properties[] = {{')
                private.extend(f'    {{{literal(key)}, &{child}, {str(required).lower()}}},' for key,child,required in props)
                private.append('};')
                fields.extend([f'.properties = {name}_properties',f'.property_count = {len(props)}'])
        elif typ=='array':fields.extend([f'.items = &{schema(s["items"])}',f'.max_items = {s["maxItems"]}'])
        elif typ=='string':
            fields.append(f'.max_length = {s.get("maxLength",64)}')
            fields.append(f'.min_length = {s.get("minLength",0)}')
            if 'format' in s:fields.append('.format = '+literal(s['format']))
        elif typ in ('integer','number'):
            fields.extend(['.minimum = '+str(s.get('minimum','-DBL_MAX')),'.maximum = '+str(s.get('maximum','DBL_MAX'))])
            if 'multipleOf' in s:fields.extend(['.multiple = '+str(s['multipleOf']),'.multiple_decimal = '+literal(str(s['multipleOf']))])
        if 'enum' in s:fields.append('.enumeration = '+literal('|'.join(str(v).lower() if isinstance(v,bool) else str(v) for v in s['enum'])))
        if s.get('const') is True:fields.append('.true_only = true')
        private.append(f'static const cs_node_t {name} = {{'+', '.join(fields)+'};')
        return name
    op_schemas=[schema(o['arguments']) for o in data['operations']]
    field_schemas=[schema(f['schema']) for f in data['configuration']]
    def mask(names):return ' | '.join('CP_SCOPE_'+n.upper().replace('.','_') for n in names) or '0'
    private.append('static const cp_operation_info_t operations[] = {')
    for o in data['operations']:
        private.append('    {'+f'.id={o["id"]}, .name={literal(o["name"])}, .scopes={mask(o["scopes"])}, '+', '.join('.'+k+'='+str(o[k]).lower() for k in ['input','ui_context','safety','read_only','sensitive','initial_v1_supported'])+'},')
    private += ['};','static const cs_node_t *const argument_schemas[] = {']+[f'    &{s},' for s in op_schemas]+['};']
    flags=['acquire','renew','script_movement','privacy','update_authority','original_authority','conditional_safety']
    private += ['bool cp_operation_flag(cp_operation_id_t id, const char *flag) {','    switch (id) {']
    for o in data['operations']:
        present=[f for f in flags if o.get(f)]
        if present:private.append(f'    case {o["id"]}: return '+' || '.join(f'strcmp(flag, {literal(f)}) == 0' for f in present)+';')
    private += ['    default: return false;','    }','}']
    private += ['size_t cp_operation_count(void) { return sizeof(operations)/sizeof(operations[0]); }',
                'const cp_operation_info_t *cp_operation_at(size_t i) { return i < cp_operation_count() ? &operations[i] : NULL; }',
                'const cp_operation_info_t *cp_operation_find(const char *name) { for (size_t i=0;i<cp_operation_count();++i) if (strcmp(name,operations[i].name)==0) return &operations[i]; return NULL; }',
                'const cs_node_t *cp_argument_schema(cp_operation_id_t id) { return id && id <= cp_operation_count() ? argument_schemas[id-1] : NULL; }']
    private += ['const char *cp_catalog_sha256(void) { return '+literal(hashlib.sha256(CATALOG.read_bytes()).hexdigest())+'; }']
    private += ['static const char *const scopes[] = {'+', '.join(literal(s) for s in scopes)+'};',
                'const char *cp_scope_name(size_t i) { return i < sizeof(scopes)/sizeof(scopes[0]) ? scopes[i] : NULL; }',
                'cp_scope_mask_t cp_scope_from_name(const char *name) { for(size_t i=0;i<sizeof(scopes)/sizeof(scopes[0]);++i) if(strcmp(name,scopes[i])==0) return UINT64_C(1)<<i; return 0; }']
    private += ['static const cp_config_info_t config_fields[] = {']
    for f,s in zip(data['configuration'],field_schemas):
        default=json.dumps(f['default'],ensure_ascii=True,separators=(',',':'))
        private.append('    {'+', '.join([literal(f['key']),'&'+s,mask([f['scope']]),literal(default),literal(f['apply_policy']),literal(f['persistence']),str(f.get('sensitive',False)).lower()])+'},')
    private += ['};','size_t cp_config_count(void) { return sizeof(config_fields)/sizeof(config_fields[0]); }',
                'const cp_config_info_t *cp_config_at(size_t i) { return i < cp_config_count() ? &config_fields[i] : NULL; }',
                'const cp_config_info_t *cp_config_find(const char *key) { for(size_t i=0;i<cp_config_count();++i) if(strcmp(key,config_fields[i].key)==0) return &config_fields[i]; return NULL; }']
    envelope={'v':{'const':1},'boot_id':{'type':'string','pattern':'^[0-9a-f]{32}$'},'session_id':{'type':'string','pattern':'^[0-9a-f]{32}$'},'request_id':{'type':'string','pattern':'^[0-9a-f]{32}$'},'seq':{'type':'integer','minimum':1,'maximum':4294967295},'deadline_ms':{'type':'string','format':'uint64'},'management_generation':{'type':['string','null'],'format':'uint64'},'resource_revision':{'type':['string','null'],'format':'uint64'},'epoch':{'type':['string','null'],'format':'uint64'},'transport_generation':{'type':['string','null'],'format':'uint64'},'target_id':{'type':['string','null'],'maxLength':64},'lease_id':{'type':['string','null'],'format':'id128'},'ui_revision':{'type':['string','null'],'format':'uint64'},'op':{'type':'string'},'args':{'type':'object'}}
    command={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:esp32-input:command:v1','type':'object','additionalProperties':False,'properties':envelope,'required':['v','boot_id','session_id','request_id','seq','deadline_ms','op','args'],'oneOf':[{'properties':{'op':{'const':o['name']},'args':o['arguments']}} for o in data['operations']]}
    openapi={'openapi':'3.1.0','info':{'title':'ESP32 Input authenticated control','version':'1.0.0'},'servers':[{'url':'https://{device}','variables':{'device':{'default':'device.invalid'}}}],'security':[{'nativeSession':[]},{'browserSession':[]}],'paths':{'/api/v1/commands':{'post':{'operationId':'commands','requestBody':{'required':True,'content':{'application/json':{'schema':command}}},'responses':{'200':{'description':'Known terminal result or duplicate'},'202':{'description':'Accepted bounded work; not hardware completion'},'400':{'description':'Rejected schema or identity'},'401':{'description':'Unauthenticated'},'403':{'description':'Forbidden scope/origin/CSRF'},'409':{'description':'Stale or conflicting state'},'503':{'description':'Unavailable capability/resource'}}}}},'components':{'securitySchemes':{'nativeSession':{'type':'http','scheme':'bearer'},'browserSession':{'type':'apiKey','in':'cookie','name':'__Host-control'}}}}
    for name in ['state','capabilities','operations','config','config/schema','jobs/{id}','requests/{id}','wifi/scans/{id}','wifi/profiles','bluetooth/peers','firmware/releases','audio/state','audio/capabilities','imu','firmware/policy','speech/state','recordings','capture/grants','clock','trust','sessions/current','firmware/state']:
        openapi['paths']['/api/v1/'+name]={'get':{'responses':{'200':{'description':'Scoped bounded resource; paginate metadata'},'401':{'description':'Unauthenticated'},'403':{'description':'Forbidden'},'503':{'description':'Provider unavailable'}}}}
        if '{id}' in name:openapi['paths']['/api/v1/'+name]['get']['parameters']=[{'name':'id','in':'path','required':True,'schema':{'type':'string','maxLength':64}}]
    openapi['paths']['/api/v1/ws-ticket']={'post':{'description':'Browser cookie, exact Origin and X-CSRF-Token required. Empty JSON-content-type POST issues one random ticket, replacing the previous ticket for this session. Consume once before WSS upgrade within 10000 ms.','parameters':[{'name':'X-CSRF-Token','in':'header','required':True,'schema':{'type':'string','pattern':'^[0-9a-f]{32}$'}}],'responses':{'200':{'description':'Single-use ticket; never log or put in URL','content':{'application/json':{'schema':O({'ticket':{'type':'string','pattern':'^[0-9a-f]{64}$'},'expires_in_ms':{'const':10000}},['ticket','expires_in_ms'])}}},'401':{'description':'Session or CSRF rejected'},'503':{'description':'WSS unavailable'}}}}
    tools=[]
    context=O({k:v for k,v in envelope.items() if k in ['management_generation','resource_revision','epoch','transport_generation','target_id','ui_revision']})
    for o in data['operations']:
        tools.append({'name':o['name'].replace('.','_'),'description':o['name']+'; authenticated device scopes and availability apply. Acceptance is not completion.','inputSchema':O({'context':context,'args':o['arguments']},['context','args']),'annotations':{'readOnlyHint':o['read_only'],'idempotentHint':False},'x-device-operation':o['name'],'x-required-scopes':o['scopes'],'x-initial-v1-supported':o['initial_v1_supported'], 'x-device-resource':o.get('resource')})
    return {
        'components/control_protocol/include/control_registry.h':'\n'.join(header)+'\n',
        'components/control_protocol/control_registry.c':'\n'.join(private)+'\n',
        'api/control-command.schema.json':json.dumps(command,indent=2)+'\n',
        'api/openapi.json':json.dumps(openapi,indent=2)+'\n',
        'bridge/tools.json':json.dumps({'schema_version':1,'tools':tools},indent=2)+'\n'}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    changed=[]
    for name,content in generate().items():
        path=ROOT/name
        if args.check:
            if not path.exists() or path.read_text()!=content:changed.append(name)
        else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
    if changed:raise SystemExit('Generated artifacts differ: '+', '.join(changed))
    print('PASS: generated control registry/schemas/MCP metadata match the catalog' if args.check else 'Generated control registry, schemas and MCP metadata')


if __name__=='__main__':main()
